edits.oldText:
// B-015: show the jump glyph when the playing track lives outside
// the browsed folder; B-031 debounces the hide.
final divergent =
    playingPath != null &&
    playingPath.isNotEmpty &&
    p.dirname(playingPath) != (path ?? '');
final showJumpGlyph = resolveJumpGlyphVisible(divergent);

edits.newText:
// B-015: show the jump glyph when the playing track lives outside
// the browsed folder; B-031 debounces the hide.
final divergent =
    playingPath != null &&
    playingPath.isNotEmpty &&
    p.dirname(playingPath) != (path ?? '');
final showJumpGlyphForDivergence =
    resolveJumpGlyphVisible(divergent);

// Linux: when the playing track is in the current folder but the
// row is scrolled out of view, expose an accessible action.
final isLinux =
    Theme.of(context).platform == TargetPlatform.linux;
final showJumpGlyph = (isLinux && !divergent &&
        playingPath != null && playingPath.isNotEmpty)
    ? () {
        final listVisible = browserPresentation.value !=
                BrowserPresentation.swipeUp ||
            browserExpanded.value;
        final inView = listVisible
            ? browserController.isTrackInView(playingPath)
            : false;
        return !inView;
      }()
    : showJumpGlyphForDivergence;

